key","definition":"PRIMARY KEY (id)"},{"name":"supplier_switch_requests_process_type_check","definition":"CHECK (((process_type IS NULL) OR (process_type = ANY (ARRAY['supplier_switch_existing_site'::text, 'move_in'::text, 'move_out'::text, 'takeover'::text, 'unknown'::text]))))"},{"name":"supplier_switch_requests_prodat_variant_check","definition":"CHECK (((prodat_variant IS NULL) OR (prodat_variant = ANY (ARRAY['L'::text, 'LK'::text, 'H'::text]))))"},{"name":"supplier_switch_requests_z03_variant_check","definition":"CHECK (((z03_variant IS NULL) OR (z03_variant = ANY (ARRAY['L'::text, 'LK'::text, 'H'::text]))))"}]}
E035_TASK3B_NATIVE_NORMALIZER {"name":"gridex_assign_customer_contract_identity_v1()","definition":"CREATE OR REPLACE FUNCTION public.gridex_assign_customer_contract_identity_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nbegin\n  if new.customer_id is null or new.company_id is null then\n    return new;\n  end if;\n\n  if nullif(btrim(new.customer_number),'') is null then\n    select c.customer_number into new.customer_number\n    from public.customers c\n    where c.id=new.customer_id and c.company_id=new.company_id;\n  end if;\n  if nullif(btrim(new.customer_number),'') is null then\n    raise exception using errcode='23502',message='customer_contract_customer_number_required';\n  end if;\n\n  if nullif(btrim(new.contract_number),'') is null then\n    new.contract_number := public.gridex_next_contract_number(new.company_id,new.customer_number);\n  end if;\n  return new;\nend\n$function$\n"}
E035_TASK3B_NATIVE_NORMALIZER {"name":"gridex_enforce_customer_contract_chain_v1()","definition":"CREATE OR REPLACE FUNCTION public.gridex_enforce_customer_contract_chain_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare\n  v_row jsonb:=to_jsonb(new);\n  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;\n  v_customer_id uuid:=nullif(v_row->>'customer_id','')::uuid;\n  v_contract_id uuid:=coalesce(\n    nullif(v_row->>'customer_contract_id','')::uuid,\n    nullif(v_row->>'contract_id','')::uuid\n  );\n  v_metering_point_id uuid:=nullif(v_row->>'metering_point_id','')::uuid;\n  v_underlay_id uuid:=nullif(v_row->>'billing_underlay_id','')::uuid;\n  v_export_item_id uuid:=coalesce(\n    nullif(v_row->>'invoice_export_item_id','')::uuid,\n    nullif(v_row->>'canonical_export_item_id','')::uuid\n  );\nbegin\n  if v_company_id is null or v_customer_id is null then\n    raise exception using errcode='23502',message='customer_chain_company_customer_required';\n  end if;\n  if v_contract_id is not null and not exists(\n    select 1 from public.customer_contracts cc\n    where cc.id=v_contract_id\n      and cc.company_id=v_company_id\n      and cc.customer_id=v_customer_id\n  ) then\n    raise exception using errcode='23514',message='customer_chain_contract_mismatch';\n  end if;\n  if v_metering_point_id is not null and not exists(\n    select 1 from public.metering_points mp\n    where mp.id=v_metering_point_id\n      and mp.company_id=v_company_id\n      and mp.customer_id=v_customer_id\n  ) then\n    raise exception using errcode='23514',message='customer_chain_metering_point_mismatch';\n  end if;\n  if v_underlay_id is not null and not exists(\n    select 1 from public.billing_underlays bu\n    where bu.id=v_underlay_id\n      and bu.company_id=v_company_id\n      and bu.customer_id=v_customer_id\n      and (\n        v_contract_id is null\n        or coalesce(bu.customer_contract_id,bu.contract_id)=v_contract_id\n      )\n  ) then\n    raise exception using errcode='23514',message='customer_chain_underlay_mismatch';\n  end if;\n  if v_export_item_id is not null and not exists(\n    select 1 from public.invoice_export_items iei\n    where iei.id=v_export_item_id\n      and iei.company_id=v_company_id\n      and iei.customer_id=v_customer_id\n      and (\n        v_contract_id is null\n        or iei.customer_contract_id=v_contract_id\n      )\n  ) then\n    raise exception using errcode='23514',message='customer_chain_export_item_mismatch';\n  end if;\n  return new;\nend\n$function$\n"}
E035_TASK3B_NATIVE_NORMALIZER {"name":"gridex_fill_customer_contract_price_area_v1()","definition":"CREATE OR REPLACE FUNCTION public.gridex_fill_customer_contract_price_area_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare\n  v_site_area text; v_meter_area text; v_site_grid text; v_meter_grid text; v_area text; v_grid text;\nbegin\n  if new.customer_site_id is not null or new.site_id is not null then\n    select upper(nullif(btrim(s.price_area_code),'')), upper(nullif(btrim(s.grid_area_code),'')) into v_site_area,v_site_grid\n    from public.customer_sites s where s.id=coalesce(new.customer_site_id,new.site_id) and s.company_id=new.company_id limit 1;\n  end if;\n  if new.metering_point_id is not null then\n    select upper(nullif(btrim(coalesce(m.price_area_code,m.price_area)),'')), upper(nullif(btrim(m.grid_area_code),'')) into v_meter_area,v_meter_grid\n    from public.metering_points m where m.id=new.metering_point_id and m.company_id=new.company_id limit 1;\n  end if;\n  if v_site_area in ('SE1','SE2','SE3','SE4') and v_meter_area in ('SE1','SE2','SE3','SE4') and v_site_area<>v_meter_area then\n    raise exception using errcode='23514',message='contract_price_area_source_conflict';\n  end if;\n  v_area:=coalesce(case when v_meter_area in ('SE1','SE2','SE3','SE4') then v_meter_area end,case when v_site_area in ('SE1','SE2','SE3','SE4') then v_site_area end);\n  v_grid:=coalesce(v_meter_grid,v_site_grid);\n  if nullif(btrim(coalesce(new.price_area_used,'')),'') is null then new.price_area_used:=v_area;\n  elsif v_area is not null and upper(btrim(new.price_area_used))<>v_area then raise exception using errcode='23514',message='contract_price_area_binding_mismatch';\n  else new.price_area_used:=upper(btrim(new.price_area_used)); end if;\n  if nullif(btrim(coalesce(new.grid_area_code_used,'')),'') is null then new.grid_area_code_used:=v_grid;\n  elsif v_grid is not null and upper(btrim(new.grid_area_code_used))<>v_grid then raise exception using errcode='23514',message='contract_grid_area_binding_mismatch';\n  else new.grid_area_code_used:=upper(btrim(new.grid_area_code_used)); end if;\n  return new;\nend; $function$\n"}
E035_TASK3B_NATIVE_NORMALIZER {"name":"gridex_lock_signed_customer_contract()","definition":"CREATE OR REPLACE FUNCTION public.gridex_lock_signed_customer_contract()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_catalog', 'pg_temp'\nAS $function$\ndeclare\n  v_old jsonb := to_jsonb(old);\n  v_new jsonb := to_jsonb(new);\n  v_immutable_keys text[] := array[\n    'company_id','customer_id','contract_name','contract_type',\n    'energy_direction','site_id','customer_site_id','metering_point_id',\n    'contract_offer_id','public_contract_offer_id','offer_reference',\n    'quote_reference','contract_product_id','contract_product_version_id',\n    'contract_publication_version_id','price_plan_id',\n    'price_plan_version_id','price_book_id','legal_bundle_version_id',\n    'contract_price_snapshot_id','commercial_snapshot','legal_snapshot',\n    'legal_versions_snapshot','tenant_communication_snapshot',\n    'tenant_communication_snapshot_sha256','tenant_legal_party_snapshot',\n    'signature_snapshot','signature_snapshot_sha256',\n    'price_snapshot','campaign_snapshot','fixed_price_ore_per_kwh',\n    'spot_markup_ore_per_kwh','variable_fee_ore_per_kwh',\n    'markup_ore_per_kwh','monthly_fee_sek','invoice_fee_sek',\n    'discount_value','discount_unit','start_fee_sek','admin_fee_sek',\n    'break_fee_sek','vat_rate','green_fee_mode','green_fee_value',\n    'binding_months','notice_months','optional_fee_lines','starts_at',\n    'expected_start_at','ends_at','auto_renew_enabled',\n    'auto_renew_term_months','terms_version','terms_signed_version',\n    'signed_version','signed_at','signed_ip_hash','signed_user_agent'\n  ];\n  v_key text;\nbegin\n  if tg_op='DELETE' then\n    if old.status in ('signed','active','terminated','cancelled','expired')\n       or old.signed_at is not null or old.locked_at is not null then\n      raise exception using errcode='55000',message='signed_customer_contract_delete_forbidden';\n    end if;\n    return old;\n  end if;\n\n  if old.status in ('signed','active','terminated','cancelled','expired')\n     or old.signed_at is not null or old.locked_at is not null then\n    foreach v_key in array v_immutable_keys loop\n      if v_new->v_key is distinct from v_old->v_key then\n        raise exception using errcode='55000',message='signed_customer_contract_immutable:'||v_key;\n      end if;\n    end loop;\n\n    if new.document_sha256 is distinct from old.document_sha256 then\n      if old.document_sha256 is not null\n         or coalesce(new.document_sha256,'') !~ '^[0-9a-f]{64}$'\n         or not exists(\n           select 1 from public.customer_contract_documents d\n           where d.company_id=old.company_id\n             and d.customer_contract_id=old.id\n             and d.document_type='signed_contract_pdf'\n             and d.document_sha256=new.document_sha256\n             and d.verified_at is not null\n         ) then\n        raise exception using errcode='55000',message='signed_customer_contract_document_hash_binding_invalid';\n      end if;\n    end if;\n\n    new.locked_at:=coalesce(old.locked_at,old.signed_at,now());\n  elsif new.signed_at is not null or new.status in ('signed','active') then\n    new.locked_at:=coalesce(new.locked_at,new.signed_at,now());\n  end if;\n  return new;\nend\n$function$\n"}
E035_TASK3B_NATIVE_NORMALIZER {"name":"gridex_normalize_customer_contract_pricing_snapshot_v1()","definition":"CREATE OR REPLACE FUNCTION public.gridex_normalize_customer_contract_pricing_snapshot_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'private', 'pg_catalog', 'pg_temp'\nAS $function$\nbegin\n  if new.price_snapshot is not null then\n    new.price_snapshot := private.gridex_normalize_fixed_area_snapshot_v1(new.price_snapshot);\n  end if;\n  return new;\nend\n$function$\n"}
E035_TASK3B_NATIVE_NORMALIZER {"name":"gridex_normalize_signature_request_event_truth_v1()","definition":"CREATE OR REPLACE FUNCTION public.gridex_normalize_signature_request_event_truth_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_catalog', 'pg_temp'\nAS $function$\nbegin\n  if new.event_type='signature_requested' and new.note is not null then\n    new.note := replace(new.note,'Signering skickad / väntar signering','Signering begärd / väntar signering');\n    new.note := replace(new.note,'Signering skickad','Signering begärd');\n  end if;\n  return new;\nend\n$function$\n"}
E035_TASK3B_NATIVE_NORMALIZER {"name":"gridex_sync_supply_customer_contract_v1()","definition":"CREATE OR REPLACE FUNCTION public.gridex_sync_supply_customer_contract_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nbegin\n  if new.contract_id is not null and new.customer_contract_id is not null\n     and new.contract_id is distinct from new.customer_contract_id then\n    raise exception using errcode='23514',message='supply_contract_alias_mismatch';\n  end if;\n  new.customer_contract_id:=coalesce(new.customer_contract_id,new.contract_id);\n  new.contract_id:=coalesce(new.contract_id,new.customer_contract_id);\n  return new;\nend\n$function$\n"}
